                    acc += qi[d] * kj[d]
                except OverflowError:
                    raise ValueError(
                        "score dot product accumulated to a non-finite value")
                if not math.isfinite(acc):
                    raise ValueError(
                        "score dot product accumulated to a non-finite value")
