                    m = sj

        # e = exp(s - m) 仅在 True 位计算；分母按 j 升序从 0.0 累加。
        e_row = [0.0] * Tk
        denom = 0.0
        for j in range(Tk):
            if active[i][j]:
                try:
                    ev = math.exp(s_row[j] - m)
                except OverflowError:
                    raise ValueError("softmax exp overflowed")
